//! Federated continual experiment-design control plane.
//!
//! Atlas feature: `AFA-metrics-P09-F32`.  This module admits typed, power-aware
//! design summaries and emits a replayable release receipt.  It never schedules
//! animals, materials, instruments, or human/clinical decisions.

use bioprism_foundation::{AuthorityRequirement, AutonomyTier, CapabilityManifest, Determinism, Effect, EvidenceReference, EvidenceState, ResearchSurface, TypedPort, TypedResearchArtifact, PRECLINICAL_BOUNDARY, RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;

pub const FEATURE_ID: &str = "AFA-metrics-P09-F32";
pub const CONTRACT_VERSION: &str = "metrics-federated-continual-experiment-design-control-plane/1.0";
pub const INPUT_SCHEMA: &str = "ExperimentObjective4@1";
pub const OUTPUT_SCHEMA: &str = "ExecutableExperimentDesign8@1";
const CONTENT_TYPE: &str = "application/vnd.aurora.executable-experiment-design-8+json";

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DesignCandidate { pub design_id: String, pub factor_order: Vec<String>, pub sample_size: u64, pub power_milli: u64, pub effect_digest: ContentHash, pub provenance_digest: ContentHash, pub baseline_digest: ContentHash, pub semantic_profile: String, pub evidence_state: EvidenceState, pub omissions: Vec<String>, pub uncertainty: Vec<String>, pub negative_result: bool, pub local_data: bool, pub permitted: bool, pub cost_units: u64 }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ExperimentObjective { pub schema_version: String, pub objective_id: String, pub federation_id: String, pub institution_id: String, pub semantic_profile: String, pub required_factor_order: Vec<String>, pub comparability_digest: ContentHash, pub replay_identity: ContentHash, pub candidates: Vec<DesignCandidate>, pub budget_units: u64, pub policy_allow: bool, pub protected_closure: bool, pub signed_approval: bool, pub federation_approved: bool, pub raw_data_local: bool, pub aggregate_only: bool, pub adversarial_events: Vec<String>, pub boundary: String }
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DesignDisposition { Qualified, Unresolved, Blocked }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ExecutableExperimentDesign { pub schema_version: String, pub contract_version: String, pub feature_id: String, pub objective_id: String, pub federation_id: String, pub institution_id: String, pub semantic_profile: String, pub disposition: DesignDisposition, pub candidate_order: Vec<String>, pub selected_order: Vec<String>, pub unresolved_order: Vec<String>, pub blocked_order: Vec<String>, pub underpowered_order: Vec<String>, pub missing_factor_order: Vec<String>, pub omission_order: Vec<String>, pub uncertainty_order: Vec<String>, pub negative_evidence_order: Vec<String>, pub replay_identity: ContentHash, pub design_digest: ContentHash, pub artifact: TypedResearchArtifact, pub effect_receipts: Vec<String>, pub raw_data_local: bool, pub aggregate_only: bool, pub boundary: String }
#[derive(Debug, Error, Clone, PartialEq, Eq)]
pub enum ExperimentDesignError { #[error("invalid experiment objective: {0}")] Invalid(String), #[error("experiment design artifact failed: {0}")] Artifact(String) }
fn invalid(value: impl Into<String>) -> ExperimentDesignError { ExperimentDesignError::Invalid(value.into()) }
fn canonical(values: &[String]) -> bool { values.windows(2).all(|pair| pair[0] < pair[1]) }
fn digest(value: &ContentHash) -> bool { value.as_str().len() == 64 }

impl ExecutableExperimentDesign { pub fn validate(&self) -> Result<(), ExperimentDesignError> { if self.schema_version != RESEARCH_CONTRACT_SCHEMA_VERSION || self.contract_version != CONTRACT_VERSION || self.feature_id != FEATURE_ID || self.boundary != PRECLINICAL_BOUNDARY || self.artifact.boundary != PRECLINICAL_BOUNDARY || !self.raw_data_local || !self.aggregate_only || self.objective_id.trim().is_empty() || self.federation_id.trim().is_empty() || self.institution_id.trim().is_empty() || self.semantic_profile.trim().is_empty() || self.candidate_order.is_empty() || self.effect_receipts.is_empty() { return Err(invalid("experiment design identity, locality, candidates, or effects are incomplete")); } for values in [&self.candidate_order, &self.selected_order, &self.unresolved_order, &self.blocked_order, &self.underpowered_order, &self.missing_factor_order, &self.omission_order, &self.uncertainty_order, &self.negative_evidence_order, &self.effect_receipts] { if !canonical(values) { return Err(invalid("experiment design ordering is not canonical")); } } let ids = self.candidate_order.iter().cloned().collect::<BTreeSet<_>>(); let parts = self.selected_order.iter().chain(self.unresolved_order.iter()).chain(self.blocked_order.iter()).cloned().collect::<Vec<_>>(); if parts.len() != ids.len() || parts.iter().cloned().collect::<BTreeSet<_>>() != ids { return Err(invalid("experiment design states do not partition candidates")); } for value in [&self.replay_identity, &self.design_digest, &self.artifact.content_hash] { if !digest(value) { return Err(invalid("experiment design digest is invalid")); } } self.artifact.validate_metadata().map_err(|e| ExperimentDesignError::Artifact(e.to_string()))?; if self.artifact.content_type != CONTENT_TYPE { return Err(invalid("experiment design artifact type is invalid")); } if self.disposition == DesignDisposition::Qualified && self.effect_receipts != [format!("exchange:permitted-summaries:{}", self.objective_id), format!("manage:local-capability:{}", self.objective_id)] { return Err(invalid("qualified experiment design effects are invalid")); } if self.disposition != DesignDisposition::Qualified && self.effect_receipts != ["block:unsafe-release"] { return Err(invalid("non-qualified experiment design must block release")); } Ok(()) } }

pub fn experiment_design_control_plane_manifest() -> CapabilityManifest { CapabilityManifest { schema_version: RESEARCH_CONTRACT_SCHEMA_VERSION.into(), capability_id: FEATURE_ID.into(), version: CONTRACT_VERSION.into(), owner_crate: "metrics".into(), consumers: ["research program lead".into(), "power reviewer".into(), "federation operator".into()].into(), behavior: "evaluates typed power-aware experiment designs with factor, evidence, provenance, replay, and institutional release gates without scheduling execution".into(), value: "turns underpowered, incomparable, or unauthorized design candidates into explicit machine-checkable evidence instead of silent approval".into(), inputs: vec![TypedPort { name: "experiment_objective".into(), schema: INPUT_SCHEMA.into(), required: true }], outputs: vec![TypedPort { name: "executable_experiment_design".into(), schema: OUTPUT_SCHEMA.into(), required: true }], effects: [Effect::ExecuteLocalComputation, Effect::WriteLocalArtifact, Effect::FederationExport].into(), permissions: ["operate:institution-node".into()].into(), determinism: Determinism::ByteStable, evidence: vec![EvidenceReference { source_id: "OpenTelemetry".into(), state: EvidenceState::Supported, locator: Some("https://opentelemetry.io/docs/specs/".into()) }], authority_requirements: vec![AuthorityRequirement { role: "experiment-design approver".into(), reason: "federated design summaries require institution-local authorization".into() }], autonomy_tier: AutonomyTier::A2, surfaces: [ResearchSurface::Ui, ResearchSurface::Api, ResearchSurface::Sdk, ResearchSurface::Operator, ResearchSurface::Policy].into(), boundary: PRECLINICAL_BOUNDARY.into() } }

pub fn evaluate_experiment_design(objective: &ExperimentObjective) -> Result<ExecutableExperimentDesign, ExperimentDesignError> { validate_objective(objective)?; let mut rows = objective.candidates.clone(); rows.sort_by(|a, b| b.power_milli.cmp(&a.power_milli).then_with(|| a.design_id.cmp(&b.design_id))); let mut candidate_order = rows.iter().map(|x| x.design_id.clone()).collect::<Vec<_>>(); candidate_order.sort(); let mut selected = BTreeSet::new(); let mut unresolved = BTreeSet::new(); let mut blocked = BTreeSet::new(); let mut underpowered = BTreeSet::new(); let mut omissions = BTreeSet::new(); let mut uncertainty = BTreeSet::new(); let mut negative = BTreeSet::new(); let mut spent = 0_u64; for row in &rows { if row.negative_result { negative.insert(format!("{}:negative-result", row.design_id)); } omissions.extend(row.omissions.iter().map(|x| format!("{}:{x}", row.design_id))); uncertainty.extend(row.uncertainty.iter().map(|x| format!("{}:{x}", row.design_id))); if row.evidence_state == EvidenceState::Contradicted || !row.local_data || !row.permitted { blocked.insert(row.design_id.clone()); continue; } if row.power_milli < 800 { underpowered.insert(row.design_id.clone()); unresolved.insert(row.design_id.clone()); continue; } if row.semantic_profile != objective.semantic_profile || !row.omissions.is_empty() || !row.uncertainty.is_empty() || !matches!(row.evidence_state, EvidenceState::Proven | EvidenceState::Supported) { unresolved.insert(row.design_id.clone()); continue; } if spent.saturating_add(row.cost_units) > objective.budget_units { unresolved.insert(row.design_id.clone()); omissions.insert(format!("{}:budget-exhausted", row.design_id)); continue; } spent = spent.saturating_add(row.cost_units); selected.insert(row.design_id.clone()); } let covered = rows.iter().filter(|x| selected.contains(&x.design_id)).flat_map(|x| x.factor_order.iter().cloned()).collect::<BTreeSet<_>>(); let missing_factor = objective.required_factor_order.iter().filter(|x| !covered.contains(*x)).cloned().collect::<Vec<_>>(); for factor in &missing_factor { omissions.insert(format!("{factor}:required-factor-missing")); } if !objective.policy_allow { negative.insert("request:policy-denied".into()); } if !objective.protected_closure { uncertainty.insert("request:protected-closure-incomplete".into()); } if !objective.signed_approval { uncertainty.insert("request:signed-approval-missing".into()); } if !objective.federation_approved { uncertainty.insert("request:federation-approval-missing".into()); } negative.extend(objective.adversarial_events.iter().map(|x| format!("adversarial:{x}"))); let global = !objective.policy_allow || !objective.protected_closure || !objective.signed_approval || !objective.federation_approved || !objective.raw_data_local || !objective.aggregate_only || !objective.adversarial_events.is_empty(); if global { blocked.extend(candidate_order.iter().cloned()); selected.clear(); unresolved.clear(); underpowered.clear(); omissions.insert("request:release-gate-blocked".into()); } let disposition = if global { DesignDisposition::Blocked } else if selected.is_empty() || !missing_factor.is_empty() { DesignDisposition::Unresolved } else { DesignDisposition::Qualified }; let selected_order = selected.into_iter().collect::<Vec<_>>(); let unresolved_order = unresolved.into_iter().collect::<Vec<_>>(); let blocked_order = blocked.into_iter().collect::<Vec<_>>(); let underpowered_order = underpowered.into_iter().collect::<Vec<_>>(); let omission_order = omissions.into_iter().collect::<Vec<_>>(); let uncertainty_order = uncertainty.into_iter().collect::<Vec<_>>(); let negative_evidence_order = negative.into_iter().collect::<Vec<_>>(); let effect_receipts = if disposition == DesignDisposition::Qualified { vec![format!("exchange:permitted-summaries:{}", objective.objective_id), format!("manage:local-capability:{}", objective.objective_id)] } else { vec!["block:unsafe-release".into()] }; let payload = json!({"schema_version": RESEARCH_CONTRACT_SCHEMA_VERSION, "contract_version": CONTRACT_VERSION, "feature_id": FEATURE_ID, "objective_id": objective.objective_id, "federation_id": objective.federation_id, "institution_id": objective.institution_id, "semantic_profile": objective.semantic_profile, "disposition": disposition, "candidate_order": candidate_order, "selected_order": selected_order, "unresolved_order": unresolved_order, "blocked_order": blocked_order, "underpowered_order": underpowered_order, "missing_factor_order": missing_factor, "omission_order": omission_order, "uncertainty_order": uncertainty_order, "negative_evidence_order": negative_evidence_order, "replay_identity": objective.replay_identity, "effect_receipts": effect_receipts, "raw_data_local": objective.raw_data_local, "aggregate_only": objective.aggregate_only, "boundary": PRECLINICAL_BOUNDARY}); let design_digest = ContentHash::of_value(&payload).map_err(|e| ExperimentDesignError::Artifact(e.to_string()))?; let artifact = TypedResearchArtifact::from_payload(format!("executable-experiment-design:{}", objective.objective_id), CONTENT_TYPE, &payload, Vec::new(), Vec::new()).map_err(|e| ExperimentDesignError::Artifact(e.to_string()))?; let receipt = ExecutableExperimentDesign { schema_version: RESEARCH_CONTRACT_SCHEMA_VERSION.into(), contract_version: CONTRACT_VERSION.into(), feature_id: FEATURE_ID.into(), objective_id: objective.objective_id.clone(), federation_id: objective.federation_id.clone(), institution_id: objective.institution_id.clone(), semantic_profile: objective.semantic_profile.clone(), disposition, candidate_order: payload["candidate_order"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().into()).collect(), selected_order: payload["selected_order"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().into()).collect(), unresolved_order: payload["unresolved_order"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().into()).collect(), blocked_order: payload["blocked_order"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().into()).collect(), underpowered_order: payload["underpowered_order"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().into()).collect(), missing_factor_order: payload["missing_factor_order"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().into()).collect(), omission_order: payload["omission_order"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().into()).collect(), uncertainty_order: payload["uncertainty_order"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().into()).collect(), negative_evidence_order: payload["negative_evidence_order"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().into()).collect(), replay_identity: objective.replay_identity.clone(), design_digest, artifact, effect_receipts: payload["effect_receipts"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().into()).collect(), raw_data_local: objective.raw_data_local, aggregate_only: objective.aggregate_only, boundary: PRECLINICAL_BOUNDARY.into() }; receipt.validate()?; Ok(receipt) }
fn validate_objective(objective: &ExperimentObjective) -> Result<(), ExperimentDesignError> { if objective.schema_version != RESEARCH_CONTRACT_SCHEMA_VERSION || objective.objective_id.trim().is_empty() || objective.federation_id.trim().is_empty() || objective.institution_id.trim().is_empty() || objective.semantic_profile.trim().is_empty() || objective.required_factor_order.is_empty() || !canonical(&objective.required_factor_order) || objective.candidates.is_empty() || objective.budget_units == 0 || !digest(&objective.comparability_digest) || !digest(&objective.replay_identity) || !canonical(&objective.adversarial_events) || !objective.raw_data_local || !objective.aggregate_only || objective.boundary != PRECLINICAL_BOUNDARY { return Err(invalid("experiment objective identity, factors, candidates, digests, budget, locality, or boundary is invalid")); } let mut ids = BTreeSet::new(); for row in &objective.candidates { if row.design_id.trim().is_empty() || !ids.insert(row.design_id.clone()) || row.factor_order.is_empty() || !canonical(&row.factor_order) || row.sample_size == 0 || !digest(&row.effect_digest) || !digest(&row.provenance_digest) || !digest(&row.baseline_digest) || row.semantic_profile.trim().is_empty() || row.cost_units == 0 || !canonical(&row.omissions) || !canonical(&row.uncertainty) { return Err(invalid(format!("design {} is malformed or duplicated", row.design_id))); } } Ok(()) }

#[cfg(test)]
mod tests { use super::*; fn h(v: &str) -> ContentHash { ContentHash::of_bytes(v.as_bytes()) } fn objective() -> ExperimentObjective { let d = h("design"); let row = |id: &str, factor: &str, power: u64| DesignCandidate { design_id: id.into(), factor_order: vec![factor.into()], sample_size: 20, power_milli: power, effect_digest: d.clone(), provenance_digest: d.clone(), baseline_digest: d.clone(), semantic_profile: "neural".into(), evidence_state: EvidenceState::Supported, omissions: vec![], uncertainty: vec![], negative_result: false, local_data: true, permitted: true, cost_units: 1 }; ExperimentObjective { schema_version: RESEARCH_CONTRACT_SCHEMA_VERSION.into(), objective_id: "objective:one".into(), federation_id: "fed:commons".into(), institution_id: "inst:alpha".into(), semantic_profile: "neural".into(), required_factor_order: vec!["factor:a".into(), "factor:b".into()], comparability_digest: d.clone(), replay_identity: d.clone(), candidates: vec![row("design:a", "factor:a", 900), row("design:b", "factor:b", 850)], budget_units: 5, policy_allow: true, protected_closure: true, signed_approval: true, federation_approved: true, raw_data_local: true, aggregate_only: true, adversarial_events: vec![], boundary: PRECLINICAL_BOUNDARY.into() } } #[test] fn manifest_is_a2() { assert_eq!(experiment_design_control_plane_manifest().autonomy_tier, AutonomyTier::A2); } #[test] fn qualified_design() { assert_eq!(evaluate_experiment_design(&objective()).unwrap().disposition, DesignDisposition::Qualified); } #[test] fn deterministic_replay() { let a = evaluate_experiment_design(&objective()).unwrap(); let b = evaluate_experiment_design(&objective()).unwrap(); assert_eq!(a.design_digest, b.design_digest); } #[test] fn underpowered_retained() { let mut r = objective(); r.candidates[0].power_milli = 500; let out = evaluate_experiment_design(&r).unwrap(); assert!(!out.underpowered_order.is_empty()); } #[test] fn missing_factor_unresolved() { let mut r = objective(); r.required_factor_order.push("factor:c".into()); assert_eq!(evaluate_experiment_design(&r).unwrap().disposition, DesignDisposition::Unresolved); } #[test] fn policy_blocks() { let mut r = objective(); r.policy_allow = false; assert_eq!(evaluate_experiment_design(&r).unwrap().disposition, DesignDisposition::Blocked); } #[test] fn adversarial_blocks() { let mut r = objective(); r.adversarial_events.push("prompt-injection".into()); assert_eq!(evaluate_experiment_design(&r).unwrap().disposition, DesignDisposition::Blocked); } }
